WHERE fs.base_ym = #{condition.baseYm}

    AND (
        fs.customer_id LIKE CONCAT(#{condition.customerId}, '%')
        OR c.display_name LIKE CONCAT('%', #{condition.customerId}, '%')
    )


    AND pr.risk_grade = #{condition.riskGrade}


    AND pr.prediction_id IS NULL


    AND pr.prediction_id IS NOT NULL
    AND pr.llm_status = 'COMPLETED'
    AND pr.prompt_version = #{condition.promptVersion}


    AND pr.prediction_id IS NOT NULL
    AND pr.llm_status = 'COMPLETED'
    AND (pr.prompt_version IS NULL OR pr.prompt_version != #{condition.promptVersion})


    AND pr.prediction_id IS NOT NULL AND pr.llm_status = 'FAILED'



        AND pr.hazard_1m >= #{condition.minRiskRate}
        AND pr.hazard_2m >= #{condition.minRiskRate}
        AND pr.hazard_3m >= #{condition.minRiskRate}




        AND pr.hazard_1m <= #{condition.maxRiskRate}
        AND pr.hazard_2m <= #{condition.maxRiskRate}
        AND pr.hazard_3m <= #{condition.maxRiskRate}
